function flip(key, value){
  const any = key === 'fruta' && value === 'cualquiera';
  const on = any ? api.fruitAny : api.sel[key].has(value);
  if (!on && !any && api.sel[key].size >= api.MAX_PICK){
    const why = document.getElementById('why');
    if (why){
      why.hidden = false;
      why.textContent = 'Cinco es el tope.';
    }
    return;
  }
  const adding = !on;
  api.togglePick(key, {v:value, t:value}, {checked:!on});
  if (adding && (any ? api.fruitAny : api.sel[key].has(value))){
    freshKey = 'f:' + value;
  }
  api.moveFocus = false;
  api.persist();
  renderStage();
  focusPick(value);
}

