  const mark = 'f:';
  const b = api.el('button', {
    type:'button',
    class: cls(className, on && 'is-on', freshKey === mark + item.v && 'is-fresh'),
    'data-pick': item.v,
    'aria-pressed': on ? 'true' : 'false'
  });
